import React from 'react';
import { motion } from 'framer-motion';

const Hero = () => {
  return (
    <motion.section
      initial={{ opacity: 0, y: 50 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.8, ease: "easeOut" }}
      className="mb-20"
    >
      <div className="flex flex-col-reverse lg:flex-row gap-12 items-start">
        <motion.div
          initial={{ opacity: 0, x: -50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: 0.2, duration: 0.8 }}
          className="lg:w-2/3"
        >
          <motion.h1
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3, duration: 0.6 }}
            className="text-4xl md:text-5xl font-black text-gray-900 dark:text-white mb-2"
          >
            Simon Doe
          </motion.h1>
          <motion.h2
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.4, duration: 0.6 }}
            className="text-xl md:text-2xl text-gray-500 dark:text-gray-400 font-light mb-6"
          >
            Senior Software Engineer
          </motion.h2>
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.5, duration: 0.6 }}
            className="text-lg leading-relaxed mb-6 text-gray-600 dark:text-gray-300"
          >
            I'm a software engineer specialised in frontend and backend
            development for complex scalable web apps. I write about
            software development on{' '}
            <a className="text-primary hover:underline font-medium" href="#">
              my blog
            </a>
            . Want to know how I may help your project? Check out my
            project{' '}
            <a className="text-primary hover:underline font-medium" href="#">
              portfolio
            </a>{' '}
            and{' '}
            <a className="text-primary hover:underline font-medium" href="#">
              online resume
            </a>
            .
          </motion.p>
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.6, duration: 0.6 }}
            className="flex flex-wrap gap-4"
          >
            <motion.button
              whileHover={{ scale: 1.05, y: -2 }}
              whileTap={{ scale: 0.95 }}
              className="bg-primary hover:bg-primary-dark text-white font-bold py-3 px-6 rounded shadow-md transition-transform transform hover:-translate-y-0.5"
            >
              <i className="fas fa-arrow-circle-right mr-2"></i> View Portfolio
            </motion.button>
            <motion.button
              whileHover={{ scale: 1.05, y: -2 }}
              whileTap={{ scale: 0.95 }}
              className="bg-gray-700 hover:bg-gray-800 dark:bg-gray-600 dark:hover:bg-gray-500 text-white font-bold py-3 px-6 rounded shadow-md transition-transform transform hover:-translate-y-0.5"
            >
              <i className="fas fa-file-alt mr-2"></i> View Resume
            </motion.button>
          </motion.div>
        </motion.div>
        <motion.div
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: 0.4, duration: 0.8 }}
          className="lg:w-1/3 w-full"
        >
          <motion.div
            whileHover={{ scale: 1.02 }}
            transition={{ type: "spring", stiffness: 300 }}
            className="relative w-full aspect-[4/3] lg:aspect-square bg-gray-200 dark:bg-gray-700 rounded-sm overflow-hidden shadow-lg"
          >
            <motion.img
              whileHover={{ scale: 1.1 }}
              transition={{ duration: 0.5 }}
              alt="Portrait of Simon Doe"
              className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-500"
              src="https://lh3.googleusercontent.com/aida-public/AB6AXuB_N2k_0JsY_TTl2IHJBZl_8sR4IwOS5pjmHt9VxDE4tQfVtClMLW8s2Lc2vH4vfo-zmy2S9HRFISj3hs2xgx6P1KDuDInId-CNoein8mDGJHn9v03w2woPG2n3Fqe43SogreWSq3A0YPJPNQfIIkSWTb0p-CEZ7UcghAYopjG2091iDG7VLX2Vi0m-ymS12SmvaxHGho7IgSu2BzgUXIqtFJzNlayqYoiHToJciP5qVMlN4KJRwgVTD8WuE7g6_QaET0r60z8Ghws"
            />
          </motion.div>
        </motion.div>
      </div>
    </motion.section>
  );
};

export default Hero;
